{"command":"cd /testbed && python3 - <<'EOF'
import json
from pathlib import Path
rep = json.loads(Path("REPORT.json").read_text())
status = json.loads(Path("status.json").read_text())
brief = json.loads(Path("release_brief.json").read_text())

def keys(o, p=""):
    out = set()
    if isinstance(o, dict):
        for k, v in o.items():
            out.add(p + k); out |= keys(v, p + k + ".")
    return out

# status keys at top level
print("status keys missing:", keys(status) - keys(rep))
print("status values altered:", [k for k,v in status.items() if rep.get(k) != v])
# brief keys under release
bk = {("release." + k) for k in keys(brief)}
print("brief keys missing:", bk - keys(rep))
def walk(a, b, p=""):
    diffs = []
    if isinstance(a, dict):
        for k, v in a.items():
            diffs += walk(v, (b or {}).get(k) if isinstance(b, dict) else None, p+k+".")
    elif a != b:
        diffs.append((p.rstrip("."), a, b))
    return diffs
print("brief value diffs:", walk(brief, rep["release"]))
print("readiness keys:", sorted(rep["readiness"]))
EOF"}
